/**
 * Stalwart Popup Registration Function
 * @param {domEvents,fnOpenPopup,intervalTimeMs} props 
 */
var stRegisterPopup = (function(props){
    /* props has all the properties */
    props = props || {};

    /***************Common Variables - Start**************/
    
    /*List of existing DOM events to be handled as Valid User Interation. Default is `click`*/
    var userInterationDOMEvents = (Array.isArray(props.domEvents) && props.domEvents) || ['click'];

    /*Flag to control popup behavior when interval is running*/
    var showPopup = true;
    
    /*Interval time in milliseconds. Default is 10 seconds*/
    var intervalTimeMs = props.intervalTimeMs || 10000; 
    
    /*Interval function's unique ID. This is required to kill interval loop.*/
    var intervalId;
    
    /*Interval count to check interval iteration executed. One interation is executed after `intervalTimeMs`*/
    var intervalCnt = 0;

    /*This flag is set to true when interval is terminated and no longer going to be executed.*/
    var intervalTerminated = false;

    /***************Common Variables - End**************/


    /***************Function Handlers - Start***************/

    /**
     * This function generates function for EventListener handles ie addEventListener, removeEventListener, etc. 
     * @param eventNames Valid & Registered DOM events
     * @param listnerType Valid prefix to EventListener function handlers ie. document.{prefix}EventListener
     */
    var generateEventListenerHandlers = function(eventNames){
        var EVENT_LISTENER = 'EventListener';
        var domEventHandlerPrefixes = ['add','remove'];
        var domEventHandlerAliases = ['register','unregister'];
        return domEventHandlerPrefixes.map(function(v,i){
            return {name: v, alias: (domEventHandlerAliases.length-1) >= i ? domEventHandlerAliases[i] : v}
        }).reduce(function(acc,listnerType){            
            return (acc[listnerType.alias] = function(eventHandler){
                eventNames.forEach(function(eventName){
                    document[listnerType.name+EVENT_LISTENER](eventName,eventHandler);
                });
            }) && acc;
        },{});
    }
    var domEventListners = generateEventListenerHandlers(userInterationDOMEvents)

    /** Function Handler to reset showPopup flag. 
    * This is used to suppress popup open in every interval iteration
    */
    var fnResetShowPopup = function(e){
        showPopup = false;
        console.info("User interacted!! | EventName: ",e.type);
    }

   
    /*Replace this function body with popup open code or function call*/
    var fnOpenPopup = props.fnOpenPopup || function(){
        alert("Default Popup opened!! Please register your popup handler to open custom popup!!"); 
    }

    /**
     * This function is executed for every iteration on interval `intervalTimeMs`.
     * Logic:
     *  - If user is idle ie. showPopup is true then,
     *      - Call show popup handler `fnOpenPopup`
     *      - Stop Interval so popup is not opened once it is opened.
     *      - Unregister the event listeners so they are no more executed on User Interactions.
     *  - If user is interacting, then it will not open the popup as showPopup value is false and wait for next iteration after `intervalTimeMs`.
     */
    var fnIntervalPopup = function(){
        console.info("Interval count => ",intervalCnt);
        if(showPopup){            
            fnOpenPopup();
            clearInterval(intervalId);
            intervalTerminated = true;
            domEventListners.unregister(fnResetShowPopup);
        }else{
            showPopup = true;
        }
        intervalCnt++;
    }

    var fnPopupStatus = function popupStatus(){
        return {
            terminated : intervalTerminated,
            iterationCount : intervalCnt,
            registeredDOMEvents: [].concat(userInterationDOMEvents)
        }
    }

    /***************Function Handlers - End***************/

    domEventListners.register(fnResetShowPopup);

    intervalId = setInterval(fnIntervalPopup,intervalTimeMs);

    return fnPopupStatus;
}); 

