//Change Date Format

function convertDate(dateString)
{
var date = new Date(dateString);
var d = date.getDate();
var m = date.getMonth() +1;
var y = date.getFullYear();
return m+"/"+d+"/"+y;
}


dateChanger = function(date){
  debugger;
var newDate = new Date(date);
var d = newDate.getDate();
var m = newDate.getMonth() +1;
var y = newDate.getFullYear();
return y+"-"+m+"-"+d;
};


isGreaterThenIncorporationDate = function(date,incorporationDate){
	var inputDate = new Date(date);
	var dateOfIncorporation = new Date(incorporationDate);
	return (inputDate>dateOfIncorporation);
};


isNotFutureDate = function(date){
	var inputDate = new Date(date);
	var systemDate = new Date();
	return (inputDate<=systemDate);

};





function popUp(popUpName){
    $("#"+popUpName).on('shown.bs.modal', function (event) {
        
         event.currentTarget.style.opacity = 1;
         $('.modal-backdrop.fade')[0].style.opacity=0.5
     });
     $("#"+popUpName).on('hiden.bs.modal', function (event) {
        
         event.currentTarget.style.opacity = 1;
         $('.modal-backdrop.fade')[0].style.opacity=0
     });
}
